diff --git a/cmd/entire/cli/checkpoint/checkpoint.go b/cmd/entire/cli/checkpoint/checkpoint.go
index e254f8b83..7dbeb9157 100644
--- a/cmd/entire/cli/checkpoint/checkpoint.go
+++ b/cmd/entire/cli/checkpoint/checkpoint.go
@@ -280,11 +280,6 @@ type WriteCommittedOptions struct {
 	// CheckpointTranscriptStart is written to both CommittedMetadata.CheckpointTranscriptStart
 	// and the deprecated CommittedMetadata.TranscriptLinesAtStart for backward compatibility.

-	// CompactTranscriptStart is the transcript.jsonl line offset at checkpoint start.
-	// V2 /main writes this to checkpoint_transcript_start; v1 continues to use
-	// CheckpointTranscriptStart (full.jsonl).
-	CompactTranscriptStart int
-
 	// TokenUsage contains the token usage for this checkpoint
 	TokenUsage *agent.TokenUsage

@@ -314,11 +309,6 @@ type WriteCommittedOptions struct {
 	//   - the checkpoint predates the summarization feature
 	Summary *Summary

-	// CompactTranscript is the Entire Transcript Format (transcript.jsonl) bytes.
-	// Written to v2 /main ref alongside metadata. May be nil if compaction
-	// was not performed (unknown agent, compaction error, empty transcript).
-	CompactTranscript []byte
-
 	// Kind identifies the session purpose (e.g., "agent_review"). Empty for normal sessions.
 	Kind string

@@ -359,10 +349,6 @@ type UpdateCommittedOptions struct {
 	// Agent identifies the agent type (needed for transcript chunking)
 	Agent types.AgentType

-	// CompactTranscript is the updated Entire Transcript Format bytes.
-	// If non-nil, replaces the existing transcript.jsonl on v2 /main.
-	CompactTranscript []byte
-
 	// PrecomputedBlobs, if non-nil, provides chunk blob hashes and the
 	// content-hash blob hash computed once for this transcript. When set,
 	// UpdateCommitted skips the per-call ChunkTranscript + zlib work and
@@ -374,11 +360,6 @@ type UpdateCommittedOptions struct {
 // PrecomputedTranscriptBlobs holds blob hashes for a transcript that was
 // chunked and written to the object store once, for reuse across multiple
 // UpdateCommitted calls sharing the same transcript content.
-//
-// Blob hashes are content-addressed (SHA-1 of chunk bytes), so the same
-// PrecomputedTranscriptBlobs works for both v1 (full.jsonl) and v2
-// (raw_transcript) paths — only the tree-entry filename differs.
-//
 // Callers should avoid constructing this for empty transcripts; agent.ChunkTranscript
 // would otherwise produce a single zero-length chunk and a hash for an empty
 // blob, which downstream stores would never reference.
diff --git a/cmd/entire/cli/checkpoint/committed.go b/cmd/entire/cli/checkpoint/committed.go
index 998e90595..8d5db04b6 100644
--- a/cmd/entire/cli/checkpoint/committed.go
+++ b/cmd/entire/cli/checkpoint/committed.go
@@ -1641,10 +1641,6 @@ func (s *GitStore) replaceTranscript(ctx context.Context, transcript redact.Reda
 // plus the content-hash blob to the object store once, returning the resulting
 // hashes for reuse across multiple UpdateCommitted calls that share the same
 // transcript content.
-//
-// The returned blobs work for both v1 (full.jsonl) and v2 (raw_transcript)
-// paths since blob hashes are content-addressed (SHA-1 of chunk bytes). Only
-// the tree-entry filenames differ between v1 and v2.
 func PrecomputeTranscriptBlobs(ctx context.Context, repo *git.Repository, transcript redact.RedactedBytes, agentType types.AgentType) (*PrecomputedTranscriptBlobs, error) {
 	raw := transcript.Bytes()

diff --git a/cmd/entire/cli/checkpoint/committed_reader_resolve.go b/cmd/entire/cli/checkpoint/committed_reader_resolve.go
index 3634bf111..c5aeb665a 100644
--- a/cmd/entire/cli/checkpoint/committed_reader_resolve.go
+++ b/cmd/entire/cli/checkpoint/committed_reader_resolve.go
@@ -47,7 +47,6 @@ type committedReadMode int
 const (
 	committedReadV1 committedReadMode = iota
 	committedReadDual
-	committedReadV2
 )

 // CommittedReaderOptions configures NewCommittedReader.
@@ -55,7 +54,7 @@ type CommittedReaderOptions struct {
 	BlobFetcher BlobFetchFunc
 }

-func NewCommittedReader(ctx context.Context, repo *git.Repository, opts CommittedReaderOptions) (CommittedStore, error) { //nolint:ireturn // Factory selects among v1, v2, and dual reader implementations.
+func NewCommittedReader(ctx context.Context, repo *git.Repository, opts CommittedReaderOptions) (CommittedStore, error) { //nolint:ireturn // Factory selects between v1 and dual reader implementations.
 	if repo == nil {
 		return nil, errors.New("git repository is required")
 	}
@@ -82,8 +81,6 @@ func NewCommittedReader(ctx context.Context, repo *git.Repository, opts Committe
 	}

 	switch mode {
-	case committedReadV2:
-		return v2Store, nil
 	case committedReadDual:
 		return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
 	case committedReadV1:
@@ -94,10 +91,7 @@ func NewCommittedReader(ctx context.Context, repo *git.Repository, opts Committe
 }

 func resolveCommittedReadMode(checkpointsV2Enabled bool, checkpointsVersion int, localV2MainRef bool) committedReadMode {
-	if checkpointsVersion == 2 {
-		return committedReadV2
-	}
-	if checkpointsV2Enabled || localV2MainRef {
+	if checkpointsV2Enabled || checkpointsVersion == 2 || localV2MainRef {
 		return committedReadDual
 	}
 	return committedReadV1
@@ -332,21 +326,7 @@ func (r *DualCheckpointReader) ListCommitted(ctx context.Context) ([]CommittedIn
 }

 func (r *DualCheckpointReader) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
-	err := r.v2.UpdateSummary(ctx, checkpointID, summary)
-	if err == nil {
-		return nil
-	}
-	if ctxErr := ctx.Err(); ctxErr != nil {
-		return ctxErr //nolint:wrapcheck // Propagating context cancellation
-	}
-	if !errors.Is(err, ErrCheckpointNotFound) {
-		return fmt.Errorf("update v2 checkpoint summary: %w", err)
-	}
-	fallbackErr := r.v1.UpdateSummary(ctx, checkpointID, summary)
-	if fallbackErr == nil {
-		return nil
-	}
-	return fallbackReadError(err, "update v1 checkpoint summary", fallbackErr)
+	return r.v1.UpdateSummary(ctx, checkpointID, summary)
 }

 func (r *DualCheckpointReader) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
diff --git a/cmd/entire/cli/checkpoint/git_common_dir.go b/cmd/entire/cli/checkpoint/git_common_dir.go
index b776c6ae6..5a9aa44fc 100644
--- a/cmd/entire/cli/checkpoint/git_common_dir.go
+++ b/cmd/entire/cli/checkpoint/git_common_dir.go
@@ -22,8 +22,11 @@ func resolveGitCommonDir(ctx context.Context, repo *git.Repository) (string, err
 	}

 	cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
-	output, err := cmd.Output()
+	output, err := cmd.CombinedOutput()
 	if err != nil {
+		if detail := strings.TrimSpace(string(output)); detail != "" {
+			return "", fmt.Errorf("resolve git common dir: %w: %s", err, detail)
+		}
 		return "", fmt.Errorf("resolve git common dir: %w", err)
 	}
 	commonDir := strings.TrimSpace(string(output))
diff --git a/cmd/entire/cli/checkpoint/v2_read.go b/cmd/entire/cli/checkpoint/v2_read.go
index 5dd2b042f..1a85413ff 100644
--- a/cmd/entire/cli/checkpoint/v2_read.go
+++ b/cmd/entire/cli/checkpoint/v2_read.go
@@ -259,6 +259,12 @@ func (s *V2GitStore) ReadSessionPrompts(ctx context.Context, checkpointID id.Che
 	return content, nil
 }

+// GetCheckpointAuthor retrieves the author of a checkpoint from the v2 /main
+// commit history.
+func (s *V2GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
+	return getCheckpointAuthorFromRef(ctx, s.repo, plumbing.ReferenceName(paths.V2MainRefName), checkpointID)
+}
+
 // ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
 // and the raw transcript (raw_transcript) from /full/current.
 // This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
@@ -372,12 +378,24 @@ func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointI
 		return transcript, nil
 	}

+	// Skip refs already scanned pre-fetch. Use a membership set rather than a
+	// length boundary: archive ref names can interleave in lex order across
+	// machines (clocks diverge per the fetchRemoteFullRefs comment), so a new
+	// ref may sort before existing local ones.
+	checkedArchived := make(map[plumbing.ReferenceName]struct{}, len(archived))
+	for _, ref := range archived {
+		checkedArchived[ref] = struct{}{}
+	}
 	archived, err = s.listArchivedFullRefs()
 	if err != nil {
 		return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume.
 	}
 	for i := len(archived) - 1; i >= 0; i-- {
-		transcript, err := s.readTranscriptFromRef(archived[i], sessionPath, agentType)
+		ref := archived[i]
+		if _, checked := checkedArchived[ref]; checked {
+			continue
+		}
+		transcript, err := s.readTranscriptFromRef(ref, sessionPath, agentType)
 		if err == nil && len(transcript) > 0 {
 			return transcript, nil
 		}
